import type { RandomSource } from './random';

export type BotTurnPhase = 'idle' | 'thinking' | 'aiming' | 'shooting' | 'done';

export interface BotTurnTiming {
  thinkSeconds: number;
  aimSeconds: number;
  shootSeconds: number;
}

export interface BotTurnStatus {
  phase: BotTurnPhase;
  statusText: string;
  showAimLine: boolean;
  fireShot: boolean;
  progress: number;
}

export const DEFAULT_BOT_TURN_TIMING: BotTurnTiming = {
  thinkSeconds: 0.9,
  aimSeconds: 0.8,
  shootSeconds: 0.35,
};

const THINK_JITTER_SECONDS = 0.3;
const THINK_SECONDS_PER_DEPTH = 0.25;

function personalityThinkScale(personality: string): number {
  switch (personality) {
    case 'careful':
      return 1.25;
    case 'bold':
      return 0.8;
    case 'trickster':
      return 1.1;
    default:
      return 1;
  }
}

function sanitizeTiming(timing: Partial<BotTurnTiming> | undefined): BotTurnTiming {
  const merged = { ...DEFAULT_BOT_TURN_TIMING, ...timing };
  return {
    thinkSeconds: Math.max(0, merged.thinkSeconds),
    aimSeconds: Math.max(0, merged.aimSeconds),
    shootSeconds: Math.max(0, merged.shootSeconds),
  };
}

function phaseProgress(elapsed: number, duration: number): number {
  if (duration <= 0) return 1;
  return Math.min(1, Math.max(0, elapsed / duration));
}

/** Think time grows with planning depth and personality, with optional deterministic jitter. */
export function timingForProfile(
  personality: string,
  planningDepth: number,
  random?: RandomSource,
): BotTurnTiming {
  const depthBonus = Math.max(0, planningDepth - 1) * THINK_SECONDS_PER_DEPTH;
  const scaled = (DEFAULT_BOT_TURN_TIMING.thinkSeconds + depthBonus) * personalityThinkScale(personality);
  const jitter = random ? random() * THINK_JITTER_SECONDS : 0;
  return { ...DEFAULT_BOT_TURN_TIMING, thinkSeconds: scaled + jitter };
}

/**
 * Time driven state machine that paces a bot turn: think, aim, shoot.
 * Driven purely by the dt handed to update(), so it is testable without timers.
 */
export class BotTurnScheduler {
  private readonly baseTiming: BotTurnTiming;
  private readonly random: RandomSource | undefined;
  private timing: BotTurnTiming;
  private currentPhase: BotTurnPhase = 'idle';
  private clock = 0;
  private botName = '';
  private shotFired = false;

  constructor(timing?: Partial<BotTurnTiming>, random?: RandomSource) {
    this.baseTiming = sanitizeTiming(timing);
    this.random = random;
    this.timing = { ...this.baseTiming };
  }

  get phase(): BotTurnPhase {
    return this.currentPhase;
  }

  get activeTiming(): BotTurnTiming {
    return { ...this.timing };
  }

  begin(botName: string, personality?: string): void {
    this.botName = botName;
    this.clock = 0;
    this.shotFired = false;
    this.currentPhase = 'thinking';
    if (personality === undefined) {
      this.timing = { ...this.baseTiming };
      return;
    }
    const jitter = this.random ? this.random() * THINK_JITTER_SECONDS : 0;
    this.timing = {
      ...this.baseTiming,
      thinkSeconds: this.baseTiming.thinkSeconds * personalityThinkScale(personality) + jitter,
    };
  }

  reset(): void {
    this.currentPhase = 'idle';
    this.clock = 0;
    this.botName = '';
    this.shotFired = false;
    this.timing = { ...this.baseTiming };
  }

  update(dt: number): BotTurnStatus {
    if (this.currentPhase === 'idle') return this.status('idle', false, false, 0);
    if (this.currentPhase === 'done') return this.status('done', false, false, 1);

    this.clock += Math.max(0, dt);
    const aimStart = this.timing.thinkSeconds;
    const shootStart = aimStart + this.timing.aimSeconds;
    const shootEnd = shootStart + this.timing.shootSeconds;

    if (this.clock < aimStart) {
      this.currentPhase = 'thinking';
      return this.status('thinking', false, false, phaseProgress(this.clock, this.timing.thinkSeconds));
    }
    if (this.clock < shootStart) {
      this.currentPhase = 'aiming';
      return this.status('aiming', true, false, phaseProgress(this.clock - aimStart, this.timing.aimSeconds));
    }
    const shootProgress = phaseProgress(this.clock - shootStart, this.timing.shootSeconds);
    if (!this.shotFired) {
      this.shotFired = true;
      this.currentPhase = 'shooting';
      return this.status('shooting', false, true, shootProgress);
    }
    if (this.clock < shootEnd) {
      this.currentPhase = 'shooting';
      return this.status('shooting', false, false, shootProgress);
    }
    this.currentPhase = 'done';
    return this.status('done', false, false, 1);
  }

  private status(
    phase: BotTurnPhase,
    showAimLine: boolean,
    fireShot: boolean,
    progress: number,
  ): BotTurnStatus {
    let statusText = '';
    if (phase === 'thinking') statusText = `${this.botName} is thinking`;
    else if (phase === 'aiming') statusText = `${this.botName} is aiming`;
    return { phase, statusText, showAimLine, fireShot, progress };
  }
}
