cat > src/ai/scheduler.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { BotTurnScheduler, DEFAULT_BOT_TURN_TIMING, timingForProfile } from './BotTurnScheduler';
import type { BotTurnPhase, BotTurnStatus } from './BotTurnScheduler';
import { createSeededRandom } from './random';

const FAST_TIMING = { thinkSeconds: 0.4, aimSeconds: 0.4, shootSeconds: 0.2 };

const run = (scheduler: BotTurnScheduler, steps: number, dt = 0.1): BotTurnStatus[] => {
  const frames: BotTurnStatus[] = [];
  for (let index = 0; index < steps; index += 1) frames.push(scheduler.update(dt));
  return frames;
};

const phaseOrder = (frames: readonly BotTurnStatus[]): BotTurnPhase[] => {
  const order: BotTurnPhase[] = [];
  for (const frame of frames) {
    if (order[order.length - 1] !== frame.phase) order.push(frame.phase);
  }
  return order;
};

describe('BotTurnScheduler', () => {
  it('walks the phases in order and never shoots on the first update', () => {
    const scheduler = new BotTurnScheduler(FAST_TIMING);
    scheduler.begin('Nova');
    const frames = run(scheduler, 20);
    expect(frames[0]?.phase).toBe('thinking');
    expect(frames[0]?.fireShot).toBe(false);
    expect(phaseOrder(frames)).toEqual(['thinking', 'aiming', 'shooting', 'done']);
    expect(scheduler.phase).toBe('done');
  });

  it('emits fireShot exactly once per turn', () => {
    const scheduler = new BotTurnScheduler(FAST_TIMING);
    scheduler.begin('Nova');
    const fired = run(scheduler, 40).filter((frame) => frame.fireShot);
    expect(fired).toHaveLength(1);
    expect(fired[0]?.phase).toBe('shooting');
  });

  it('still fires once when a single large step skips past every phase', () => {
    const scheduler = new BotTurnScheduler(FAST_TIMING);
    scheduler.begin('Nova');
    const jump = scheduler.update(30);
    expect(jump.fireShot).toBe(true);
    expect(jump.phase).toBe('shooting');
    expect(run(scheduler, 5).some((frame) => frame.fireShot)).toBe(false);
    expect(scheduler.phase).toBe('done');
  });

  it('shows the aim line only while aiming and keeps progress normalized', () => {
    const scheduler = new BotTurnScheduler(FAST_TIMING);
    scheduler.begin('Nova');
    for (const frame of run(scheduler, 20)) {
      expect(frame.showAimLine).toBe(frame.phase === 'aiming');
      expect(frame.progress).toBeGreaterThanOrEqual(0);
      expect(frame.progress).toBeLessThanOrEqual(1);
    }
  });

  it('labels thinking and aiming with the bot name', () => {
    const scheduler = new BotTurnScheduler(FAST_TIMING);
    scheduler.begin('Ada');
    const frames = run(scheduler, 20);
    expect(frames.find((frame) => frame.phase === 'thinking')?.statusText).toBe('Ada is thinking');
    expect(frames.find((frame) => frame.phase === 'aiming')?.statusText).toBe('Ada is aiming');
    expect(frames.find((frame) => frame.phase === 'done')?.statusText).toBe('');
  });

  it('makes careful bots think longer than bold bots', () => {
    const careful = timingForProfile('careful', 2);
    const bold = timingForProfile('bold', 2);
    expect(careful.thinkSeconds).toBeGreaterThan(bold.thinkSeconds);
    const seededCareful = timingForProfile('careful', 2, createSeededRandom('careful-seed'));
    const seededBold = timingForProfile('bold', 2, createSeededRandom('bold-seed'));
    expect(seededCareful.thinkSeconds).toBeGreaterThan(seededBold.thinkSeconds);
  });

  it('scales think time with planning depth and keeps jitter bounded', () => {
    const shallow = timingForProfile('balanced', 1);
    const deep = timingForProfile('balanced', 3);
    expect(shallow.thinkSeconds).toBeCloseTo(DEFAULT_BOT_TURN_TIMING.thinkSeconds, 6);
    expect(deep.thinkSeconds).toBeCloseTo(DEFAULT_BOT_TURN_TIMING.thinkSeconds + 0.5, 6);
    expect(deep.aimSeconds).toBe(DEFAULT_BOT_TURN_TIMING.aimSeconds);
    const jittered = timingForProfile('balanced', 1, createSeededRandom('jitter'));
    expect(jittered.thinkSeconds).toBeGreaterThanOrEqual(shallow.thinkSeconds);
    expect(jittered.thinkSeconds).toBeLessThan(shallow.thinkSeconds + 0.3);
  });

  it('applies the personality multiplier passed to begin', () => {
    const framesUntilAim = (personality: string): number => {
      const scheduler = new BotTurnScheduler();
      scheduler.begin('Nova', personality);
      let steps = 0;
      while (scheduler.update(0.05).phase === 'thinking') steps += 1;
      return steps;
    };
    expect(framesUntilAim('careful')).toBeGreaterThan(framesUntilAim('bold'));
  });

  it('resets to idle and restarts the clock on begin', () => {
    const scheduler = new BotTurnScheduler(FAST_TIMING);
    scheduler.begin('Nova');
    run(scheduler, 20);
    scheduler.reset();
    expect(scheduler.phase).toBe('idle');
    expect(scheduler.update(5)).toEqual({
      phase: 'idle',
      statusText: '',
      showAimLine: false,
      fireShot: false,
      progress: 0,
    });
    scheduler.begin('Nova');
    expect(scheduler.update(0.05).phase).toBe('thinking');
  });
});
